.theme-dark {
	--background-primary: rgb(32, 32, 30);
	--background-secondary: rgb(41, 40, 39);

	/* --divider-color: rgb(115, 115, 115); */

	--code-block-background: #313131;
	--code-block-border: white;
	--code-comment: rgb(150, 150, 150);
}

.theme-light {
	/* --background-primary: rgb(247, 235, 216);
	--background-secondary: rgb(235, 215, 182); */

	/* --divider-color: rgb(209, 198, 179); */
	--code-block-background: #d8d8d8;
	--code-block-border: black;

	--ribbon-background-collapsed: var(--background-secondary);
}

