	--font-text-theme: "iA Writer Quattro S";

	/* Monospaced Content (code blocks / inline code */
	--font-monospace-theme: "Adwaita Mono";
}

/* 
	--------------
	| Navigation |
	--------------
*/

/* Highlight active file with accent color */
.nav-files-container {
	--nav-item-background-active: var(--interactive-accent);
	--nav-item-color-active: var(--text-on-accent);
	--nav-item-weight-active: bold;
}

/* Remove background color on active file when renaming a file, so that it has an outline instead */
.tree-item-self.is-being-renamed:focus-within {
	--nav-item-color-active: var(--text-normal);
	background-color: transparent;
}

/* Ensure text remains legible if mouse hovers over text box while renaming */
.tree-item-self.is-being-renamed:focus-within:hover {
	--nav-item-color-active: var(--text-on-accent);
}

/* 
	----------------
	| Misc. Tweaks |
	----------------
*/

/* 
	## Caret & Cursor
*/

/* Ensure that the caret is visible regardless of background color */
body.fancy-cursor .markdown-source-view.mod-cm6 .cm-content,
body .markdown-source-view.mod-cm6 .cm-content,
body.fancy-cursor .mod-cm6 .cm-line {
	caret-color: auto;
}


/* Add a small border to the VIM cursor to make it visible in highlight blocks */
.cm-fat-cursor,
.CodeMirror-cursor {
	border: 1px var(--background-primary) solid !important;
}

/* 
	## List Elements
*/

/* NOTE: first selection is for edit mode, second is for READ view */

/* Secondary bullet is a hollowed circle */
.HyperMD-list-line-2 .list-bullet:after,
.el-ul>ul>li>ul>li>.list-bullet:after {
	height: 4px;
	width: 4px;
	background-color: transparent;
	border-style: solid;
	border-radius: 50%;
	border-width: 1px;
}

/* Tertiary bullet is a square */
.HyperMD-list-line-3 .list-bullet:after,
.el-ul>ul>li>ul>li>ul>li>.list-bullet:after {
	height: 5px;
	width: 5px;
	border-radius: 0%;
}

/* Quaternary bullet is a hollowed square */
.HyperMD-list-line-4 .list-bullet:after,
.el-ul>ul>li>ul>li>ul>li>ul>li>.list-bullet:after {
	height: 4px;
	width: 4px;
	background-color: transparent;
	border-style: solid;
	border-radius: 0%;
	border-width: 1px;
}

/* 
	## Internal Links F5C35A
*/

/* Remove link underline from resolved internal note-to-note links */
:root body {
	--link-decoration: none;
	--link-decoration-hover: none;
}

/* Add dashed line under unresolved internal links */
.is-unresolved,
.markdown-rendered .internal-link.is-unresolved {
	text-decoration: underline dashed !important;
}

/* 
	## Highlighting
*/

/* Add horizontal padding to highlight when in READ view */
mark {
	padding: 0 4px;
}

/* Make highlights solid accent color */
.cm-highlight,
mark {
	background: var(--interactive-accent) !important;
}

/* Ensure that strikethrough matches text color in highlighted text */
del:has(mark) {
	color: var(--text-on-accent);
}

/* Ensure that text in a highlight gets text-on-accent to avoid visibility issues */
.cm-highlight,
.cm-highlight.cm-hmd-internal-link>.is-unresolved>span,
.cm-highlight.cm-hmd-internal-link>.is-unresolved,
mark,
mark>a,
.markdown-rendered mark .internal-link {
	color: var(--text-on-accent) !important;
}

/* Re-add regular underline to resolved internal links (to make them stand out from regular highlighted text) */
.cm-highlight.cm-hmd-internal-link>:not(.is-unresolved),
.markdown-rendered mark .internal-link,
mark>a:not(.is-unresolved) {
	text-decoration: underline !important;
	text-underline-offset: 1.5px;
}

/* 
	## Code Blocks
*/

/* Make code block background a bit lighter so it can be seen better against regular background */
code,
.cm-inline-code,
.HyperMD-codeblock.HyperMD-codeblock-bg.cm-line,
pre {
	background-color: var(--code-block-background) !important;
}

/* Add small white border around code blocks in READ view for additional styling */
pre,
code:not(pre>code) {
	border: 0.5px var(--code-block-border) solid !important;
}
